public class Solution {
    public int search(int[] nums, int target) {
        int l=0, r=nums.length;  // r должен быть length-1
        while (l<=r) {
            int m = (l+r)/2;
            if (nums[m]==target) return m;  // ArrayIndexOutOfBounds когда m=length
            if (nums[m]<target) l=m+1; else r=m-1;
        }
        return -1;
    }
}

