public class Solution {
    public int climbStairs(int n) {
        int[] dp = new int[n];  // не учитывает n=0 → отрицательный размер
        dp[0]=1; dp[1]=2;
        for (int i=2; i<n; i++) dp[i]=dp[i-1]+dp[i-2];
        return dp[n-1];
    }
}

